254e: 60                        RTS                  ;     Return to caller
254f: d0 01     loc_254f        BNE loc_2552         ; Else If (dat_199c == 0) Then  (NOP)
2551: 60        loc_2551        RTS                  ;     Return to caller
                                                     ; End If
