257c: b1 f2                     LDA (dat_00f2_L),Y   ;         Set
257e: 9d be 25                  STA dat_25be,X       ;             dat_25be[X] = (*dat_00f2_L)[Y]
2581: b1 f0                     LDA (dat_00f0_L),Y   ;         Set
2583: 8d c2 25                  STA dat_25c2         ;             dat_25c2 = (*dat_00f0_L)[Y]
2586: 8a                        TXA                  ;         Set A
2587: 0a                        ASL                  ;               =
2588: 0a                        ASL                  ;                 X * 4
2589: a8                        TAY                  ;         Set Y = A
